public class Main {
    static int N;
    static int[] S, A;
    static HashMap<Long, Boolean> memo;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int T = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();
        while (T-- > 0) {
            N = Integer.parseInt(br.readLine().trim());
            S = new int[N]; A = new int[N];
            for (int i = 0; i < N; i++) {
                StringTokenizer st = new StringTokenizer(br.readLine());
                S[i] = Integer.parseInt(st.nextToken());
                A[i] = Integer.parseInt(st.nextToken());
            }
            memo = new HashMap<>();
            boolean res = solve(0, 0);
            sb.append(res ? "Yes" : "No").append("\n");
        }
        System.out.print(sb);
    }

    static boolean solve(int round, int x) {
        if (round == N) return x == 0;
        long key = ((long)round << 32) | (x & 0xFFFFFFFFL);
        Boolean cached = memo.get(key);
        if (cached != null) return cached;
        boolean r1 = solve(round + 1, x);
        boolean r2 = solve(round + 1, x ^ A[round]);
        boolean res;
        if (S[round] == 0) res = r1 || r2;
        else res = r1 && r2;
        memo.put(key, res);
        return res;
    }
}

