    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int T = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();

        while (T-- > 0) {
            int N = Integer.parseInt(br.readLine().trim());
            StringTokenizer st = new StringTokenizer(br.readLine());
            long[] A = new long[N];
            int[] S = new int[N];
            for (int i = 0; i < N; i++) {
                A[i] = Long.parseLong(st.nextToken());
            }
            st = new StringTokenizer(br.readLine());
            for (int i = 0; i < N; i++) {
                S[i] = Integer.parseInt(st.nextToken());
            }

            long xorAll = 0;
            for (long a : A) xorAll ^= a;

            // If total XOR is 0, Person 0 can force final x = 0 regardless of choices
            if (xorAll == 0) {
                sb.append("0\n");
                continue;
            }

            // Check if Person 1 has a move on the highest bit of xorAll
            long highestBit = Long.highestOneBit(xorAll);
            boolean person1CanControl = false;
            for (int i = 0; i < N; i++) {
                if ((A[i] & highestBit) != 0 && S[i] == 1) {
                    person1CanControl = true;
                    break;
                }
            }

            // If Person 1 can flip that bit, they win; otherwise Person 0 wins.
            sb.append(person1CanControl ? "1\n" : "0\n");
        }

        System.out.print(sb);
    }
}

