// Returns 1 if person 0 wins (x=0 at end), 0 if person 1 wins
// Use recursion with the observation that we go forward
int solve(int round, long long x) {
    if (round == N) return x == 0;
    int s = S[round];
    long long a = A[round];
    // option 1: do nothing, x stays
    // option 2: x ^= a
    int r1 = solve(round + 1, x);
    int r2 = solve(round + 1, x ^ a);
    if (s == 0) return r1 || r2; // person 0 wants x=0
    else return r1 && r2; // person 1 wants x!=0
}

