/*
Key fact:
Let V0 be the linear span (over GF(2)) of all A_i controlled by person 0,
and V1 be the span of all A_i controlled by person 1.

After all rounds, person 0 can make x any value in V0, and person 1 can make
an independent XOR contribution from V1. Final x is in the coset v0 XOR v1.

Person 0 wants final x = 0 no matter what optimal play implies, while person 1
wants non-zero. With optimal play, person 0 can force 0 iff every move person 1
can create is also reproducible by person 0, i.e. V1 ⊆ V0.

So we:
1) Build XOR basis of person 0's numbers.
2) Check whether every person 1 number is representable by that basis.
If yes -> person 0 wins, answer 0.
Else -> person 1 can force non-zero, answer 1.
*/

#define MAXB 61

typedef struct {
    ll b[MAXB];
} Basis;

void basis_init(Basis *bs) {
    for (int i = 0; i < MAXB; ++i) bs->b[i] = 0;
}

void basis_add(Basis *bs, ll x) {
    for (int i = MAXB - 1; i >= 0; --i) {
        if (((x >> i) & 1LL) == 0) continue;
        if (!bs->b[i]) {
            bs->b[i] = x;
            return;
        }
        x ^= bs->b[i];
    }
}

int basis_can_make(Basis *bs, ll x) {
    for (int i = MAXB - 1; i >= 0; --i) {
        if (((x >> i) & 1LL) == 0) continue;
        if (!bs->b[i]) return 0;
        x ^= bs->b[i];
    }
    return 1;
}

int main(void) {
    int T;
    if (scanf("%d", &T) != 1) return 0;

    while (T--) {
        int N;
        scanf("%d", &N);

        ll *A = (ll *)malloc(sizeof(ll) * N);
        int *S = (int *)malloc(sizeof(int) * N);

        for (int i = 0; i < N; ++i) scanf("%lld", &A[i]);
        for (int i = 0; i < N; ++i) scanf("%d", &S[i]);

        Basis b0;
        basis_init(&b0);

        for (int i = 0; i < N; ++i) {
            if (S[i] == 0) basis_add(&b0, A[i]);
        }

        int ok = 1;
        for (int i = 0; i < N; ++i) {
            if (S[i] == 1 && !basis_can_make(&b0, A[i])) {
                ok = 0;
                break;
            }
        }

        printf("%d\n", ok ? 0 : 1);

        free(A);
        free(S);
    }

    return 0;
}

import sys
input = sys.stdin.readline

def solve():
    N = int(input())
    SA = []
    for _ in range(N):
        s, a = map(int, input().split())
        SA.append((s, a))

    # winning_set: set of x values where person 0 wins
    winning = {0}

    for i in range(N-1, -1, -1):
        s, a = SA[i]
        xored = {x ^ a for x in winning}
        if s == 0:
            winning = winning | xored
        else:
            winning = winning & xored

    print("Yes" if 0 in winning else "No")

T = int(input())
for _ in range(T):
    solve()
